  // ---- plot 7 loading platform: barrels against the outside of the back wall (x 93..94, z 18) ----
  put(g, 93, 1, 18, "barrel", { facing: "up", open: "false" });
  put(g, 94, 1, 18, "barrel", { facing: "up", open: "false" });
